130			t.Fatalf("result 1: %+v", r)
131		}
132		// 2: update to rev 2
133		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
134			t.Fatalf("result 2: %+v", r)
135		}
136		// 3: invalid content with a matching revision: still invalid, list untouched
137		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
138			t.Fatalf("result 3: %+v", r)
139		}
140		// 4: invalid address
141		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
142			t.Fatalf("result 4: %+v", r)
143		}
144		// 5: conflict on a brand-new service; actual revision 0 is still an explicit value
145		if r := got.Results[5]; r.OK || r.Error != "conflict" || !hasRevisionPair(r, 1, 0) || r.Revision != 0 {
146			t.Fatalf("result 5: %+v", r)
147		}
148		// Only the successful registrations are reflected.
149		if len(got.Services) != 1 || got.Services[0].Service != "a" || got.Services[0].Revision != 2 {
150			t.Fatalf("services: %+v", got.Services)
151		}
152		if len(got.Services[0].Instances) != 1 || got.Services[0].Instances[0].ID != "y" {
153			t.Fatalf("instances: %+v", got.Services[0].Instances)
