624	func TestSelectAddressReplacementKeepsRotation(t *testing.T) {
625		// One instance keeps its id but gets a new address: the registration bumps
626		// once, that instance resets to unknown/0 while untouched instances keep
627		// their observations, and the rotation continues after the last chosen id
628		// instead of restarting at the smallest id.
629		input := `{"requests":[
630			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
