696	func TestSelectAddressReplacementNoHealthyThenRecovery(t *testing.T) {
697		// Replacing the only healthy instance's address leaves no healthy target:
698		// select reports no_healthy without moving the cursor, a health report
699		// against the old revision conflicts without healing the new address, and
700		// a fresh observation at the current revision (sequence only above the
701		// reset 0, not above the old accepted one) makes the new address eligible
702		// again.
