707			{"type":"select","service":"svc","expectedRevision":1},
708			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"}]},
709			{"type":"select","service":"svc","expectedRevision":2},
710			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
711			{"type":"select","service":"svc","expectedRevision":2},
712			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":1,"healthy":true},
713			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":22,"healthy":true},
714			{"type":"select","service":"svc","expectedRevision":2},
715			{"type":"select","service":"svc","expectedRevision":2}
716		]}`
717		out, code := runRegisterWith(t, input)
718		if code != 1 {
719			t.Fatalf("exit code: %d, output: %s", code, out)
720		}
721		var got registerOutput
722		if err := json.Unmarshal([]byte(out), &got); err != nil {
723			t.Fatalf("output is not JSON: %v\n%s", err, out)
724		}
725		if len(got.Results) != 12 {
726			t.Fatalf("results: %+v", got.Results)
727		}
728		// Cursor rests on a before the replacement.
729		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 20 {
730			t.Fatalf("select before replacement: %+v", r)
731		}
732		if r := got.Results[4]; !r.OK || !r.Changed || r.Revision != 2 {
733			t.Fatalf("address replacement: %+v", r)
734		}
735		// No healthy instance remains: no_healthy states the reason and the current
736		// revision and fabricates neither an instance id nor an address.
737		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Reason == "" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
738			t.Fatalf("no_healthy after replacement: %+v", r)
739		}
740		// A health report against the old revision conflicts even though its
741		// sequence (99) exceeds the old accepted one (20); it names both revisions.
742		if r := got.Results[6]; r.OK || r.Error != "conflict" || r.Reason == "" || !hasRevisionPair(r, 1, 2) || r.Revision != 2 {
743			t.Fatalf("stale-revision health report: %+v", r)
744		}
745		// The conflicting report did not heal the new address: still no_healthy.
746		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
747			t.Fatalf("new address must not regain eligibility from old revision: %+v", r)
748		}
749		// At the current revision a sequence just above the reset 0 suffices; it
750		// does not need to exceed the 20 accepted for the old address.
751		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 1 {
752			t.Fatalf("fresh observation at current revision: %+v", r)
