755			t.Fatalf("b recovery: %+v", r)
756		}
757		// The failed selects and health report never moved the cursor off a, so
758		// the rotation continues at b rather than restarting at the smallest id.
759		if r := got.Results[10]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 2 {
760			t.Fatalf("rotation should resume after a at b: %+v", r)
761		}
762		// The new address rejoins selection carrying its new address and the new
763		// observation's sequence.
764		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
765			t.Fatalf("new address should be selected with its new observation: %+v", r)
