993	// TestRejectedReplacementKeepsAcceptedStateAndRotation is the regression guard
994	// for replacement requests against an existing service whose rotation is
995	// already in use: a rejected register must not partially replace instances,
996	// reset accepted health, consume a revision or move the selection position, and
997	// later selects in the same batch must keep using the previously accepted
998	// state. Two rejection conditions are exercised:
999	//
1000	//   - a list with a valid prefix that changes an existing address followed by an
1001	//     invalid instance address is invalid as a whole (field validation precedes
1002	//     the revision check, so a simultaneously wrong expectedRevision still
1003	//     reports invalid), and the valid prefix must not take effect;
1004	//   - a fully valid list with a mismatched expectedRevision is a conflict
1005	//     naming both revisions; no part of the replacement is applied.
1006	func TestRejectedReplacementKeepsAcceptedStateAndRotation(t *testing.T) {
1007		input := `{"requests":[
1008			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1009			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1010			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1011			{"type":"select","service":"svc","expectedRevision":1},
1012			{"type":"register","service":"svc","expectedRevision":9,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
1013			{"type":"select","service":"svc","expectedRevision":1},
1014			{"type":"register","service":"svc","expectedRevision":5,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
1015			{"type":"select","service":"svc","expectedRevision":1}
1016		]}`
1017		out, code := runRegisterWith(t, input)
1018		if code != 1 {
1019			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1020		}
1021		var got registerOutput
1022		if err := json.Unmarshal([]byte(out), &got); err != nil {
1023			t.Fatalf("output is not JSON: %v\n%s", err, out)
1024		}
1025		// The failed items keep their slots, in input order, with the later
1026		// successful selects still present; a later success does not cancel the
1027		// earlier failures.
1028		if len(got.Results) != 8 {
1029			t.Fatalf("results: %+v", got.Results)
1030		}
1031		// 0: accepted registration at revision 1.
1032		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
1033			t.Fatalf("result 0: %+v", r)
1034		}
1035		// 1-2: both offline health observations accepted without a revision bump.
1036		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1037			t.Fatalf("result 1: %+v", r)
1038		}
1039		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 22 {
1040			t.Fatalf("result 2: %+v", r)
1041		}
1042		// 3: first selection takes the smallest healthy id, cursor rests on i1.
1043		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 || r.Revision != 1 {
1044			t.Fatalf("result 3: %+v", r)
1045		}
1046		// 4: the later instance address is invalid. The whole item is invalid even
1047		// though expectedRevision 9 is also wrong, because field validation precedes
1048		// the revision check; the reason names the bad address and no revision
1049		// comparison is reported. The valid prefix (i1's new address) must not be
1050		// applied either.
1051		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
1052			!omitsRevisionPair(r) ||
1053			r.InstanceID != "" || r.Address != "" {
1054			t.Fatalf("result 4 invalid rejection: %+v", r)
1055		}
1056		if !strings.Contains(got.Results[4].Reason, `instance address "bad-address" is not a host:port address`) {
1057			t.Fatalf("result 4 reason should name the bad address, got %q", got.Results[4].Reason)
1058		}
1059		// 5: selection after the invalid replacement continues just after i1 and
1060		// lands on i2 using its ORIGINAL address and accepted sequence, proving the
1061		// rejected list neither reset i2 to unknown nor advanced the cursor.
1062		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1063			t.Fatalf("result 5: %+v", r)
1064		}
1065		// 6: the list itself is valid, only expectedRevision mismatches: conflict
1066		// states the expected and current revisions; no new address is accepted.
1067		if r := got.Results[6]; r.OK || r.Error != "conflict" ||
1068			r.Reason != `service "svc" is at revision 1, not 5` ||
1069			r.Revision != 1 || !hasRevisionPair(r, 5, 1) {
1070			t.Fatalf("result 6 conflict: %+v", r)
1071		}
1072		// 7: past the end the rotation wraps to the smallest healthy id, returning
1073		// i1's ORIGINAL address h1:8080 and sequence 11 — not the rejected hx:8080,
1074		// and not i2 again, which would mean the failed conflict reset the cursor.
1075		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 || r.Revision != 1 {
1076			t.Fatalf("result 7: %+v", r)
1077		}
1078	
1079		// The final service list reflects only accepted registrations and
1080		// observations: revision unchanged at 1, both original addresses, both
1081		// instances still healthy with their accepted sequences, and neither
1082		// rejected address present anywhere.
1083		if len(got.Services) != 1 {
1084			t.Fatalf("services: %+v", got.Services)
1085		}
1086		svc := got.Services[0]
1087		if svc.Service != "svc" || svc.Revision != 1 {
1088			t.Fatalf("service view: %+v", svc)
1089		}
1090		if len(svc.Instances) != 2 {
1091			t.Fatalf("instances: %+v", svc.Instances)
1092		}
1093		wantInsts := []registerInstance{
1094			{ID: "i1", Address: "h1:8080", Health: "healthy", Sequence: 11},
1095			{ID: "i2", Address: "h2:8080", Health: "healthy", Sequence: 22},
1096		}
1097		for i, want := range wantInsts {
1098			if svc.Instances[i] != want {
1099				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
1100			}
1101		}
1102	}
