1148		if out := selectedWithSession(t, r, "s2", 1, "k"); out.InstanceID != "a" {
1149			t.Fatalf("s2 bind: %+v", out)
1150		}
1151		// Move s2's rotation with a plain select; s1's binding is unaffected.
1152		if out := selected(t, r, "s2", 1); out.InstanceID != "b" {
1153			t.Fatalf("s2 plain select: %+v", out)
1154		}
