1159			t.Fatalf("s2 reuse: %+v", out)
1160		}
1161	}
1162	
1163	func TestRegistrySelectSessionFailuresKeepBindingAndCursor(t *testing.T) {
1164		r := NewRegistry()
1165		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
