218		for _, field := range []string{`"instanceId"`, `"address"`, `"sequence"`} {
219			if strings.Contains(raw, field) {
220				t.Fatalf("result 7 must carry no %s field: %s", field, raw)
221			}
222		}
223		// 8: a recovers at the higher sequence 3.
224		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 3 {
225			t.Fatalf("result 8 recovery observation: %+v", r)
226		}
227		// 9: recovery does not suspend this request's exclusion — the recovered
228		// binding a is excluded along with b, so the session falls back to the
229		// filtered rotation. The only candidate is c: the request chooses it,
230		// rebinds x -> c and advances the cursor to c.
231		if r := got.Results[9]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 1 {
232			t.Fatalf("result 9 should fall back to c and rebind: %+v", r)
