240		// healthy again and reports its latest accepted sequence 3 — the
241		// exclusions never removed a from the registry nor rewrote its record.
242		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 3 || r.Revision != 1 {
